const fs = require('fs');
const path = require('path');
const chalk = require('chalk');
const debug = require('debug');
const nodeVaultDebug = debug('node-vault');
const { getOptions } = require('./bru');
const { exists } = require('./filesystem');
const { buildSecretsConfigFromEnv } = require('./secrets-env-config');
const { interpolateString } = require('../runner/interpolate-string');
const constants = require('../constants');
const { parseDotEnv } = require('@usebruno/filestore');
const { getExternalSecretsData: fetchExternalSecretsData, setupAzureCliEnv } = require('@usebruno/requests');

const options = getOptions();

const verbose = options?.['verbose'];

if (verbose) {
  debug.enable('node-vault');
}

// Proxy/TLS config for agent resolution inside @usebruno/requests, derived from CLI run options.
// This is the only network config the shared secret-manager helpers need; they build the agents
// internally (no resolveAgents callback crosses the package boundary).
const buildNetworkConfig = () => {
  const cliOptions = getOptions();
  return {
    options: {
      noproxy: cliOptions['noproxy'] || false,
      shouldVerifyTls: !cliOptions['insecure'],
      shouldUseCustomCaCertificate: !!cliOptions['cacert'],
      customCaCertificateFilePath: cliOptions['cacert'],
      shouldKeepDefaultCaCertificates: !cliOptions['ignoreTruststore'],
      cacheSslSession: cliOptions['cacheSslSession'] || false
    },
    systemProxyConfig: cliOptions['cachedSystemProxy']
  };
};

const getExternalSecretsData = async ({ type, config, paths, collectionPath, debug }) => {
  const networkConfig = buildNetworkConfig();
  const args = {
    type,
    config,
    paths,
    networkConfig,
    debug: debug ? nodeVaultDebug : undefined
  };

  // Azure Key Vault with no provider config falls back to the Azure CLI credential (same condition
  // the shared fetch uses). Point the `az` subprocess at the run's CA bundle / TLS settings first so
  // --cacert / --insecure apply to token acquisition, then restore the env afterwards.
  const usesAzureCli = type === 'azure-key-vault' && !config?.azureConfig;
  if (!usesAzureCli) {
    return fetchExternalSecretsData(args);
  }

  // setupAzureCliEnv writes the merged CA bundle into a private per-run subdir of the collection root
  // (owned by the user running the CLI, unlike a shared /tmp path that collides across users) and
  // removes that subdir when it restores the env.
  const restoreEnv = setupAzureCliEnv({
    options: networkConfig.options,
    caBundleDir: collectionPath
  });
  try {
    return await fetchExternalSecretsData(args);
  } finally {
    restoreEnv();
  }
};

// Resolves the selected environment's external secrets into a flat variable map that the runner
// merges into request variables. Reads the provider connection config from `--secrets-env-file`
// (or falls back to the Azure CLI credential for an azure-key-vault environment), interpolates and
// fetches each declared secret, and exposes every value both with and without the `$secrets.` prefix.
// Returns {} when there's nothing to fetch. Errors are logged (under `verbose`) and never thrown.
const resolveEnvironmentExternalSecrets = async ({
  secretsEnvFile,
  collectionPath,
  environmentExternalSecrets,
  environmentExternalSecretsType,
  interpolationOptions,
  verbose
}) => {
  const externalSecretVariables = {};

  // The provider connection config comes from --secrets-env-file.
  let externalSecretsType;
  let externalSecretsProviderConfig;
  if (secretsEnvFile) {
    const secretsEnvFilePath = path.resolve(collectionPath, secretsEnvFile);
    if (!(await exists(secretsEnvFilePath))) {
      console.error(chalk.red(`Secrets env file not found: `) + chalk.dim(secretsEnvFile));
      process.exit(constants.EXIT_STATUS.ERROR_ENV_NOT_FOUND);
    }
    const secretsEnvContent = interpolateString(fs.readFileSync(secretsEnvFilePath, 'utf8'), interpolationOptions);
    const fromEnv = buildSecretsConfigFromEnv(parseDotEnv(secretsEnvContent));
    // `fromEnv.type` is the provider category (e.g. 'vault'); `fromEnv.config.type` is the specific
    // provider ('hashicorp-vault-server'), which is what the environment file declares.
    const secretsFileProviderType = fromEnv?.config?.type;
    if (!fromEnv) {
      console.error(chalk.red(`No recognised BRUNO_* secrets provider keys found in: `) + chalk.dim(secretsEnvFile));
    } else if (environmentExternalSecretsType && secretsFileProviderType !== environmentExternalSecretsType) {
      // The secrets env file provides config for a different provider than this environment declares —
      // ignore it (rather than silently fetching nothing with the wrong identifier). For an
      // azure-key-vault environment this then falls through to the Azure CLI credential.
      console.error(
        chalk.yellow(`Ignoring --secrets-env-file: it provides "${secretsFileProviderType}" config, but this environment uses "${environmentExternalSecretsType}".`)
      );
    } else {
      externalSecretsType = fromEnv.type;
      externalSecretsProviderConfig = fromEnv.config;
    }
  }

  // Azure Key Vault fallback: when the environment uses azure-key-vault but the --secrets-env-file
  // didn't supply azure provider config (not passed, or holds a different provider), fetch via the
  // Azure CLI credential instead — no client-secret config required.
  const useAzureCli
    = environmentExternalSecretsType === 'azure-key-vault'
      && !(externalSecretsType === 'azure-key-vault' && externalSecretsProviderConfig);
  if (useAzureCli) {
    externalSecretsType = 'azure-key-vault';
    externalSecretsProviderConfig = undefined;
  }

  // Secret list from the environment's external secret variables. Each provider stores its lookup
  // key under a different field: path (vault), secretName (aws), vaultName (azure),
  // projectId (gcp).
  const enabledSecrets = (environmentExternalSecrets || []).filter((v) => v.enabled !== false);

  const identifierField
    = externalSecretsType === 'aws-secrets-manager' ? 'secretName'
      : externalSecretsType === 'azure-key-vault' ? 'vaultName'
        : externalSecretsType === 'gcp-secrets-manager' ? 'projectId'
          : 'path';
  // Identifiers may reference variables (e.g. path: {{hashicorp-vault-path}}); interpolate them so
  // the resolved value is what gets sent to the provider.
  const interpolatedSecrets = enabledSecrets.map((s) => ({
    ...s,
    [identifierField]: interpolateString(s[identifierField] || '', interpolationOptions)
  }));
  // Keep only entries with a resolved identifier. This list stays positionally aligned with the
  // fetch results (providers return results in the order the paths were sent), so each result maps
  // back to its entry by index — robust to two entries resolving to the same identifier.
  const fetchableSecrets = interpolatedSecrets.filter((s) => s[identifierField]);
  const paths = fetchableSecrets.map((s) => s[identifierField]);

  if (!((externalSecretsProviderConfig || useAzureCli) && paths.length)) {
    return externalSecretVariables;
  }

  verbose && console.log(chalk.yellow('Fetching external secrets... \n'));
  try {
    const secrets = await getExternalSecretsData({
      type: externalSecretsType,
      config: externalSecretsProviderConfig,
      paths,
      collectionPath,
      debug: verbose
    });
    // getExternalSecretsData returns undefined for an unhandled provider config (e.g. a vault server
    // auth method we don't support); treat it as no secrets fetched and carry on.
    if (!Array.isArray(secrets)) {
      verbose && console.error(chalk.red('No external secrets were fetched (unsupported or incomplete provider configuration).'));
    }
    (secrets || []).forEach((s, idx) => {
      if (s?.error) {
        verbose
        && console.error(
          chalk.red(`${idx + 1}. Couldn't fetch secret for: ${paths[idx]}: `)
          + chalk.dim(`${JSON.stringify(s?.error)}`)
        );
        return;
      }
      verbose && console.log(chalk.yellow(`${idx + 1}. Fetched secret for: ${paths[idx]} \n`));
      const secretName = fetchableSecrets[idx]?.name;
      const isScalar = ['string', 'number', 'boolean'].includes(typeof s?.data);
      if (isScalar) {
        // Exposed both with and without the `$secrets.` prefix.
        externalSecretVariables[`$secrets.${secretName}`] = s?.data;
        externalSecretVariables[secretName] = s?.data;
      } else if (s?.data && typeof s.data === 'object') {
        Object.entries(s.data).forEach(([key, value]) => {
          externalSecretVariables[`$secrets.${secretName}.${key}`] = value;
          externalSecretVariables[`${secretName}.${key}`] = value;
        });
      } else {
        verbose && console.error(chalk.red(`${idx + 1}. No data returned for: ${paths[idx]}`));
      }
    });
  } catch (err) {
    verbose && console.error(chalk.red(`Fetching external secrets failed: `) + chalk.dim(`${err.message}`));
  }

  return externalSecretVariables;
};

// Whether the collection's root secrets.json holds legacy secret data for the selected environment —
// the v3 provider config that the v4 per-environment Secret Manager replaces. secrets.json stores its
// entries under `data`, keyed by environment name; an entry with secrets means that environment's
// setup hasn't been moved to the new environment-based format.
const environmentHasLegacySecretsJson = ({ collectionPath, environmentName }) => {
  if (!environmentName) return false;
  try {
    const secretsFilePath = path.join(collectionPath, 'secrets.json');
    if (!fs.existsSync(secretsFilePath)) return false;
    const secretsJsonData = JSON.parse(fs.readFileSync(secretsFilePath, 'utf8'));
    return (secretsJsonData?.data || []).some(
      (entry) => entry?.environment === environmentName && (entry?.secrets || []).length > 0
    );
  } catch (_) {
    return false;
  }
};

// Matches a legacy Secret Manager reference, e.g. {{$secrets.db.host}}.
const LEGACY_SECRET_REFERENCE = /\{\{\s*\$secrets\./;

const containsLegacySecretSyntax = (value) => LEGACY_SECRET_REFERENCE.test(JSON.stringify(value || ''));

// Set true once a request slated to run — after inheriting its collection/folder config — is found
// to still reference the removed {{$secrets.*}} syntax. It is recorded while each request is prepared
// (after inheritance is merged in, but before interpolation strips the {{$secrets.*}} marker) and
// read once at the end of the run to decide which deprecation notice to print. Reset at the start of
// every run so repeated in-process runs and tests don't leak state.
let legacySecretSyntaxDetected = false;

const resetLegacySecretSyntaxDetection = () => {
  legacySecretSyntaxDetected = false;
};

// Records whether a prepared request references the legacy {{$secrets.*}} syntax. Called once per
// request during preparation; once a single reference is seen, subsequent requests are skipped.
const recordLegacySecretSyntaxUsage = (request) => {
  if (legacySecretSyntaxDetected) return;
  if (containsLegacySecretSyntax(request)) legacySecretSyntaxDetected = true;
};

const requestsUseLegacySecretSyntax = () => legacySecretSyntaxDetected;

module.exports = {
  getExternalSecretsData,
  resolveEnvironmentExternalSecrets,
  environmentHasLegacySecretsJson,
  requestsUseLegacySecretSyntax,
  recordLegacySecretSyntaxUsage,
  resetLegacySecretSyntaxDetection
};
